import { Card, Kbd, SectionLabel } from "march/ui"

// bir uygulamanın "Klavye kısayolları" penceresi: bölümler, her satırda ne yaptığı ve tuşları
interface Shortcut { what: string; keys?: string; text?: string }

const groups: { title: string; items: Shortcut[] }[] = [
  { title: "Genel", items: [{ what: "Komut paleti", keys: "mod+k" }, { what: "Ara", keys: "mod+f" }, { what: "Pencereyi kapat", text: "Esc" }] },
  { title: "Düzenleme", items: [{ what: "Geri al", keys: "mod+z" }, { what: "Yinele", keys: "mod+shift+z" }, { what: "Kaydet", keys: "mod+s" }] },
]

// tek satır: solda açıklama, sağda tuş (kısayol dizisi ya da düz metin)
const Row = (props: { item: Shortcut }) => <div sx={{ flex: ["row", "between"], py: 1 }}>
  <span>{props.item.what}</span>
  {props.item.keys ? <Kbd keys={props.item.keys} /> : <Kbd>{props.item.text}</Kbd>}
</div>

export function ShortcutSheet() {
  return <Card title="Klavye kısayolları">
    <div sx={{ flex: "col", gap: 2 }}>
      {groups.map((g) => <div>
        <SectionLabel count={g.items.length}>{g.title}</SectionLabel>
        {g.items.map((it) => <Row item={it} />)}
      </div>)}
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { KbdLab } from "./KbdLab.tsx"

// KbdLab'in testleri: kaydedince Testler sekmesinde çalışır
test("düz metin gerçek bir <kbd> öğesinde durur", () => {
  const s = renderTest(() => <KbdLab />)
  expect(s.find("Esc")?.tagName).toBe("KBD")
  expect(s.find("Esc")?.classList.contains("m-kbd")).toBe(true)
})

test("keys platforma göre yazılır: mod sözcüğü görünmez", () => {
  const s = renderTest(() => <KbdLab />)
  const cmd = s.get(".lab-cmd")?.textContent ?? ""
  expect(cmd).toContain("K")
  expect(cmd).not.toContain("mod")
  expect(s.get(".lab-enter")?.textContent).toContain("Enter")
})

test("class m-kbd'nin yanına eklenir", () => {
  const s = renderTest(() => <KbdLab />)
  expect(s.get("kbd.lab-enter.m-kbd")).not.toBe(null)
})

test("keys canlı: alt ile'ye basınca tuş yeniden yazılır", async () => {
  const s = renderTest(() => <KbdLab />)
  const before = s.get(".lab-live")?.textContent
  await s.click("alt ile")
  const after = s.get(".lab-live")?.textContent ?? ""
  expect(after).not.toBe(before)
  expect(after).toContain("S")
})
